cat > /tmp/bot-check-$$.mjs <<'EOF'
import { decideWhatsApp } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g5-3/bot.mjs";
const T = "1767272400"; // 2026-01-01T13:00:00Z
const ms = Number(T) * 1000;
const at = (h) => new Date(ms + h * 3600e3);
const c = (over) => ({ optedIn: true, lastInboundTimestamp: T, ...over });
const cases = [
  ["text, opted, 1h after inbound", { type: "text", contact: c() }, at(1), { allowed: true, reason: null }],
  ["text, 23h59m59s after", { type: "text", contact: c() }, new Date(ms + 86399999), { allowed: true, reason: null }],
  ["text, exactly 24h", { type: "text", contact: c() }, new Date(ms + 86400000), { allowed: false, reason: "service_window_closed" }],
  ["text, 3 days after", { type: "text", contact: c() }, at(72), { allowed: false, reason: "service_window_closed" }],
  ["text, never wrote", { type: "text", contact: c({ lastInboundTimestamp: null }) }, at(1), { allowed: false, reason: "no_inbound_message" }],
  ["text, not opted in", { type: "text", contact: c({ optedIn: false }) }, at(1), { allowed: false, reason: "not_opted_in" }],
  ["template, opted, window closed", { type: "template", contact: c() }, at(72), { allowed: true, reason: null }],
  ["template, opted, never wrote", { type: "template", contact: c({ lastInboundTimestamp: null }) }, at(1), { allowed: true, reason: null }],
  ["template, not opted in", { type: "template", contact: c({ optedIn: false }) }, at(1), { allowed: false, reason: "not_opted_in" }],
  ["bad type", { type: "image", contact: c() }, at(1), { allowed: false, reason: "invalid_message_type" }],
  ["bad clock", { type: "text", contact: c() }, new Date("nope"), { allowed: false, reason: "invalid_clock" }],
  ["ms-string ts treated as seconds is rejected", { type: "text", contact: c({ lastInboundTimestamp: String(ms) }) }, at(1), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["numeric (non-string) ts rejected", { type: "text", contact: c({ lastInboundTimestamp: 1767272400 }) }, at(1), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["garbage ts", { type: "text", contact: c({ lastInboundTimestamp: "12abc" }) }, at(1), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["ts in future beyond skew", { type: "text", contact: c() }, new Date(ms - 3600e3), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["ts slightly in future (within skew)", { type: "text", contact: c() }, new Date(ms - 60e3), { allowed: true, reason: null }],
];
let fail = 0;
for (const [name, msg, now, want] of cases) {
  const got = decideWhatsApp(msg, now);
  const ok = got.allowed === want.allowed && got.reason === want.reason;
  if (!ok) fail++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
console.log(fail ? `${fail} FAILED` : "all passed");
process.exit(fail ? 1 : 0);
EOF
node /tmp/bot-check-$$.mjs; rc=$?; rm -f /tmp/bot-check-$$.mjs; exit $rc

